-- =====================================================================
--  INSTALLER LA MATIERE HLP DANS LE PIPELINE DE CORRECTION
--
--  OU  : Supabase, projet "pipeline de correction" (xgdaibekjmtffvkwvcge)
--  QUOI: SQL Editor > New query > coller UN BLOC > Run
--
--  Genere par apply-matiere.mjs le 2026-07-27, deja applique en base
--  par API le meme jour : ce fichier est la trace reproductible, pas une
--  action a refaire.
--
--  Contenu : 2 grilles, 6 sujets, 30 etalons, 2 gabarits.
--  Epreuves : hlp_essai (20 pts), hlp_interpretation (20 pts).
--
--  STATUT : tout est pose en 'draft'. Les baremes doivent etre relus par
--  des professeurs avant activation ; tant qu'ils sont en draft, les sujets
--  n'apparaissent pas dans le menu de depot et aucune copie ne peut etre
--  corrigee avec eux.
--
--  Tout le texte accentue passe par convert_from(decode(...,'hex'),'UTF8') :
--  l'editeur SQL de Supabase abime l'UTF-8 colle depuis un Mac.
--  Idempotent : chaque insert est un upsert sur la cle primaire.
-- =====================================================================


-- =====================================================================
--  BLOC A - LES 2 GRILLES
-- =====================================================================

begin;

insert into public.rubrics (id, track, matiere, exercise_type, version, status, system_prompt, rubric_json)
values ('HLP_ESSAI_V1', 'generale', 'hlp', 'hlp_essai', 1, 'draft', convert_from(decode('','hex'),'UTF8'), convert_from(decode('','hex'),'UTF8')::jsonb)
on conflict (id) do update set
  track = excluded.track, matiere = excluded.matiere, exercise_type = excluded.exercise_type,
  version = excluded.version, status = excluded.status,
  system_prompt = excluded.system_prompt, rubric_json = excluded.rubric_json;

insert into public.rubrics (id, track, matiere, exercise_type, version, status, system_prompt, rubric_json)
values ('HLP_INTERPRETATION_V1', 'generale', 'hlp', 'hlp_interpretation', 1, 'draft', convert_from(decode('','hex'),'UTF8'), convert_from(decode('','hex'),'UTF8')::jsonb)
on conflict (id) do update set
  track = excluded.track, matiere = excluded.matiere, exercise_type = excluded.exercise_type,
  version = excluded.version, status = excluded.status,
  system_prompt = excluded.system_prompt, rubric_json = excluded.rubric_json;

commit;


